<template>
  <view class="forgot-container">
    <view class="forgot-box">
      <view class="logo-area">
        <image class="logo" src="/static/logo.png"></image>
      </view>
      <text class="app-name">农业技能培训</text>
      <text class="welcome-text">重置密码</text>
      
      <!-- 步骤1：输入手机号 -->
      <view v-if="step === 1" class="step-content">
        <input 
          type="number" 
          v-model="phone" 
          placeholder="请输入手机号" 
          class="input-field"
          maxlength="11"
        />
        <button class="next-btn" @click="sendVerifyCode">获取验证码</button>
      </view>
      
      <!-- 步骤2：输入验证码和新密码 -->
      <view v-if="step === 2" class="step-content">
        <view class="verify-code-row">
          <input 
            type="number" 
            v-model="verifyCode" 
            placeholder="请输入验证码" 
            class="input-field code-input"
            maxlength="6"
          />
          <button class="code-btn" @click="sendVerifyCode" :disabled="codeBtnDisabled">
            {{ codeBtnText }}
          </button>
        </view>
        
        <input 
          type="password" 
          v-model="newPassword" 
          placeholder="请输入新密码" 
          class="input-field"
        />
        <input 
          type="password" 
          v-model="confirmPassword" 
          placeholder="请确认新密码" 
          class="input-field"
        />
        
        <button class="reset-btn" @click="resetPassword">确认重置</button>
      </view>
      
      <!-- 返回登录链接 -->
      <view class="login-link">
        <text>想起密码了？</text>
        <text class="link" @click="goToLogin">返回登录</text>
      </view>
      
      <!-- 开发者信息 -->
      <view class="dev-info">
        <text>开发者：李阳杰</text>
        <text>学号：2227010134</text>
      </view>
    </view>
  </view>
</template>

<script>
export default {
  data() {
    return {
      step: 1, // 1: 输入手机号, 2: 输入验证码和新密码
      phone: '',
      verifyCode: '',
      newPassword: '',
      confirmPassword: '',
      codeBtnDisabled: false,
      codeBtnText: '获取验证码',
      countdown: 60,
      timer: null
    }
  },
  onLoad(options) {
    console.log('忘记密码页面加载成功', options)
  },
  onUnload() {
    // 页面卸载时清除定时器
    if (this.timer) {
      clearInterval(this.timer)
    }
  },
  methods: {
    sendVerifyCode() {
      // 验证手机号
      if (!this.phone) {
        uni.showToast({
          title: '请输入手机号',
          icon: 'none'
        })
        return
      }
      
      if (!/^1[3-9]\d{9}$/.test(this.phone)) {
        uni.showToast({
          title: '手机号格式不正确',
          icon: 'none'
        })
        return
      }
      
      // 检查手机号是否已注册
      const registeredUsers = uni.getStorageSync('registeredUsers') || []
      const userExists = registeredUsers.find(user => user.phone === this.phone)
      
      if (!userExists) {
        uni.showModal({
          title: '提示',
          content: '该手机号未注册，请先注册',
          success: (res) => {
            if (res.confirm) {
              uni.navigateTo({
                url: '/pages/register/register?phone=' + this.phone
              })
            }
          }
        })
        return
      }
      
      // 模拟发送验证码
      uni.showLoading({
        title: '发送中...'
      })
      
      setTimeout(() => {
        uni.hideLoading()
        
        // 模拟验证码（实际开发中由后端发送）
        const mockCode = '123456'
        uni.setStorageSync('resetPasswordCode_' + this.phone, mockCode)
        
        uni.showToast({
          title: '验证码已发送',
          icon: 'success'
        })
        
        // 进入步骤2
        this.step = 2
        
        // 开始倒计时
        this.startCountdown()
      }, 1000)
    },
    
    startCountdown() {
      this.codeBtnDisabled = true
      this.countdown = 60
      this.codeBtnText = '60秒后重发'
      
      this.timer = setInterval(() => {
        this.countdown--
        this.codeBtnText = this.countdown + '秒后重发'
        
        if (this.countdown <= 0) {
          clearInterval(this.timer)
          this.codeBtnDisabled = false
          this.codeBtnText = '重新获取'
        }
      }, 1000)
    },
    
    resetPassword() {
      // 验证验证码
      if (!this.verifyCode) {
        uni.showToast({
          title: '请输入验证码',
          icon: 'none'
        })
        return
      }
      
      // 验证新密码
      if (!this.newPassword) {
        uni.showToast({
          title: '请输入新密码',
          icon: 'none'
        })
        return
      }
      
      if (this.newPassword.length < 6) {
        uni.showToast({
          title: '密码至少6位',
          icon: 'none'
        })
        return
      }
      
      if (this.newPassword !== this.confirmPassword) {
        uni.showToast({
          title: '两次密码不一致',
          icon: 'none'
        })
        return
      }
      
      // 验证验证码是否正确
      const savedCode = uni.getStorageSync('resetPasswordCode_' + this.phone)
      if (savedCode !== this.verifyCode) {
        uni.showToast({
          title: '验证码错误',
          icon: 'none'
        })
        return
      }
      
      uni.showLoading({
        title: '重置中...'
      })
      
      setTimeout(() => {
        // 更新密码
        const registeredUsers = uni.getStorageSync('registeredUsers') || []
        const userIndex = registeredUsers.findIndex(user => user.phone === this.phone)
        
        if (userIndex !== -1) {
          registeredUsers[userIndex].password = this.newPassword
          uni.setStorageSync('registeredUsers', registeredUsers)
        }
        
        // 清除验证码
        uni.removeStorageSync('resetPasswordCode_' + this.phone)
        
        uni.hideLoading()
        
        uni.showToast({
          title: '密码重置成功',
          icon: 'success'
        })
        
        setTimeout(() => {
          uni.navigateBack()
        }, 1500)
      }, 1000)
    },
    
    goToLogin() {
      uni.navigateBack()
    }
  }
}
</script>

